/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

/**
 * Port to deliver the notices of the alerts. observable brings the log and webhook channels; other
 * traits add theirs (observable-notification brings email through the notification outbox).
 */
public interface AlertChannel {

  /** Channel it serves: {@code log}, {@code webhook}, {@code email}... */
  boolean accepts(String channel);

  /**
   * Delivers (or enqueues) the notice.
   *
   * @throws RuntimeException if it could not: the alert keeps its notice pending and it is retried
   */
  void deliver(AlertNotification notification);
}
